.crossroads-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2620;
    background: linear-gradient(168deg, #f7f3ec 0%, #f1ece2 55%, #ece6da 100%);
    border-radius: 18px;
}

.crossroads-container * {
    box-sizing: border-box;
}

.crossroads-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #221d3a 0%, #3a2f5c 52%, #5b4a86 100%);
    color: #f6f2ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(34, 29, 58, 0.32);
}

.crossroads-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.crossroads-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f2c879;
    background: rgba(242, 200, 121, 0.13);
    border: 1px solid rgba(242, 200, 121, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.crossroads-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.6;
    color: #d8d0ec;
}

.crossroads-people {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.crossroads-person {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(34, 29, 58, 0.08);
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.crossroads-person-priya { border-left: 5px solid #c9762a; }
.crossroads-person-you { border-left: 5px solid #5b4a86; }

.crossroads-person-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #221d3a;
}

.crossroads-person-priya .crossroads-person-name { color: #b3651f; }
.crossroads-person-you .crossroads-person-name { color: #5b4a86; }

.crossroads-person-meta {
    font-size: 0.82rem;
    color: #6c6453;
    line-height: 1.45;
}

.crossroads-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a5142;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.crossroads-period-counter #currentDay,
.crossroads-period-counter #maxPeriods {
    font-weight: 800;
    color: #5b4a86;
}

.crossroads-round-name {
    background: rgba(91, 74, 134, 0.13);
    color: #4a3c72;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.crossroads-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b3651f;
    background: rgba(201, 118, 42, 0.13);
    border: 1px solid rgba(201, 118, 42, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.crossroads-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.crossroads-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(34, 29, 58, 0.08);
    border-top: 4px solid #5b4a86;
}

.crossroads-card-regret { border-top-color: #5f9268; }
.crossroads-card-stay { border-top-color: #5b4a86; }
.crossroads-card-cred { border-top-color: #c9762a; }
.crossroads-card-budget { border-top-color: #6c6453; }

.crossroads-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a8067;
}

.crossroads-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #221d3a;
    font-variant-numeric: tabular-nums;
}

.crossroads-card-regret .crossroads-value { color: #4f8159; }
.crossroads-card-stay .crossroads-value { color: #5b4a86; }
.crossroads-card-cred .crossroads-value { color: #b3651f; }
.crossroads-card-budget .crossroads-value { color: #57503f; }

.crossroads-sublabel {
    font-size: 0.76rem;
    color: #8a8067;
    line-height: 1.4;
}

/* Stay-probability danger / good states */
.crossroads-card-stay.crossroads-stay-danger { border-top-color: #c0413c; }
.crossroads-card-stay.crossroads-stay-danger .crossroads-value { color: #c0413c; }
.crossroads-card-stay.crossroads-stay-good { border-top-color: #4f8159; }
.crossroads-card-stay.crossroads-stay-good .crossroads-value { color: #4f8159; }

.crossroads-window-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e6ddcd;
    color: #5a5142;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.crossroads-window-bar #windowDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #4f8159;
    font-weight: 800;
}

.crossroads-window-bar.crossroads-window-tight #windowDisplay { color: #b3651f; }
.crossroads-window-bar.crossroads-window-closed #windowDisplay { color: #c0413c; }

.crossroads-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #5b4a86;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(34, 29, 58, 0.07);
}

.crossroads-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.crossroads-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #221d3a;
    margin-bottom: 6px;
}

.crossroads-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #463f33;
}

.crossroads-briefing-text strong { color: #5b4a86; }
.crossroads-briefing-text em { color: #b3651f; font-style: italic; }

.crossroads-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(34, 29, 58, 0.07);
}

.crossroads-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #221d3a;
    border-bottom: 2px solid #efe7d8;
    padding-bottom: 8px;
}

.crossroads-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #34301f;
    margin: 14px 0 6px;
}

.crossroads-container select,
.crossroads-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8cdb8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #2a2620;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.crossroads-container select:focus,
.crossroads-container input[type="number"]:focus {
    outline: none;
    border-color: #5b4a86;
    box-shadow: 0 0 0 3px rgba(91, 74, 134, 0.16);
}

.crossroads-container select option {
    background-color: #ffffff;
    color: #2a2620;
}

.crossroads-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #5b4a86;
}

.crossroads-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a5142;
    margin-top: 4px;
}

.crossroads-range-readout span:nth-child(2) {
    color: #5b4a86;
    font-weight: 800;
}

.crossroads-hint {
    font-size: 0.8rem;
    color: #8a8067;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.crossroads-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.crossroads-container .btn-primary {
    background: linear-gradient(135deg, #5b4a86 0%, #7c5fb0 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(91, 74, 134, 0.32);
}

.crossroads-container .btn-primary:hover {
    filter: brightness(1.07);
}

.crossroads-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d8cdb8;
    color: #6c6453;
    background: transparent;
}

.crossroads-coach {
    background: linear-gradient(160deg, #221d3a 0%, #2f2750 100%);
    color: #e8e2f5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(34, 29, 58, 0.26);
}

.crossroads-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f2c879;
    margin-bottom: 8px;
}

.crossroads-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.crossroads-coach-body strong { color: #c9a8f0; }
.crossroads-coach-body em { color: #f2c879; font-style: italic; }

.crossroads-history,
.crossroads-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(34, 29, 58, 0.07);
}

.crossroads-history h3,
.crossroads-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #221d3a;
}

.crossroads-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #463f33;
}

.crossroads-container table#usfHistoryTable th {
    background: #f3eee2;
    color: #5b4a86;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3d8c4;
}

.crossroads-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebe0;
    color: #463f33;
}

.crossroads-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.crossroads-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .crossroads-container {
        padding: 14px;
    }
    .crossroads-header h1 {
        font-size: 1.8rem;
    }
    .crossroads-people {
        flex-direction: column;
    }
    .crossroads-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .crossroads-value {
        font-size: 2rem;
    }
    .crossroads-clock {
        margin-left: 0;
    }
    .crossroads-period-counter {
        font-size: 0.88rem;
    }
    .crossroads-window-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .crossroads-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, crossroads-cm-*) ===== */
.crossroads-cm { color: #22303a; font-family: inherit; }
.crossroads-cm-generic { font-size: 15px; text-align: center; }
.crossroads-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(34,48,58,0.12); margin-bottom: 16px; }
.crossroads-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #3a7f9c; }
.crossroads-cm-score-max { font-size: 20px; font-weight: 500; color: #7b8792; margin-left: 2px; }
.crossroads-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #22303a; }
.crossroads-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #7b8792; margin-top: 4px; }
.crossroads-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.crossroads-cm-kpi { flex: 1 1 92px; min-width: 92px; background: rgba(58,127,156,0.08); border: 1px solid rgba(58,127,156,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.crossroads-cm-kpi-val { display: block; font-size: 21px; font-weight: 700; color: #22303a; }
.crossroads-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #55636e; }
.crossroads-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.crossroads-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.crossroads-cm-chip.is-met { background: rgba(46,143,107,0.14); border-color: rgba(46,143,107,0.42); color: #1f6e50; }
.crossroads-cm-chip.is-missed { background: rgba(197,74,74,0.12); border-color: rgba(197,74,74,0.4); color: #a23b3b; }
.crossroads-cm-insights { margin: 0; padding-left: 18px; }
.crossroads-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #36434e; margin-bottom: 7px; }

