(function() {
    'use strict';

    class CrossroadsLeaderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Crossroads Leader`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Aldgate Advisory, GBP).
            this.COST_OF_LOSS = 95;       // ~£95k to replace a senior analyst (£000s)
            this.ACCOUNT_AT_RISK = 1.2;   // £1.2M annual client account exposed
            this.WINDOW_DAYS = 5;         // recruiter conversation in 5 working days
            this.START_REGRET = 28;       // day-1 regret-signal resolution (0–100)
            this.START_CRED = 5.0;        // day-1 leader credibility (/10), thin
            this.SPEND_CAP = 95;          // authority/spend frame caps at the cost of loss

            // Concept truths.
            this.TRUE_DIAGNOSIS = `regret`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    regret: this.START_REGRET,     // regret-signal resolution (0–100)
                    credibility: this.START_CRED,  // leader credibility (/10)
                    budget: 0,                      // £000s of spend / commitment used
                    stayProb: 0,                    // derived stay probability (%)
                    // Sticky, run-defining penalty flags (set when an error is committed).
                    actedBlind: false,              // chose an action without diagnosing the regret signal
                    boughtMeaning: false,           // transactional fix for a meaning problem
                    defaultVirtual: false,          // thin career conversation done by quick call
                    parkedIt: false,                // urgent over important — window closed
                    overPromised: false,            // committed beyond an 8-week leader's authority
                    windowOpen: true,               // recruiter-call window still open
                    diagnosedRegret: false,         // correctly read it as a career-regret signal
                    regretHistory: [this.START_REGRET],
                    stayHistory: [0],
                    credHistory: [this.START_CRED],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the five classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    diagnosis: `pay`,
                    test: `none`,
                    credSelf: `proven`,
                    confidence: 35,
                    modality: `quickcall`,
                    timing: `afterdeadline`,
                    design: `retain`,
                    team: `hidden`,
                    action: `comp`,
                    authority: `promiseall`,
                    visibility: `overpromise`,
                    spend: 40,
                    follow: `oneoff`,
                    credRebuild: `broadcast`,
                    pipeline: `tokenise`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagnosisInput`);
                const te = document.getElementById(`testInput`);
                const cs = document.getElementById(`credSelfInput`);
                const cf = document.getElementById(`confidenceInput`);
                if (dg) decisions.diagnosis = dg.value;
                if (te) decisions.test = te.value;
                if (cs) decisions.credSelf = cs.value;
                if (cf) decisions.confidence = parseInt(cf.value, 10);
                if (!Number.isFinite(decisions.confidence) || decisions.confidence < 0 || decisions.confidence > 100) {
                    warn(`warn_confidence_range`); return false;
                }
            } else if (round === 2) {
                const mo = document.getElementById(`modalityInput`);
                const ti = document.getElementById(`timingInput`);
                const de = document.getElementById(`designInput`);
                const tm = document.getElementById(`teamInput`);
                if (mo) decisions.modality = mo.value;
                if (ti) decisions.timing = ti.value;
                if (de) decisions.design = de.value;
                if (tm) decisions.team = tm.value;
                if (!decisions.modality || !decisions.timing || !decisions.design || !decisions.team) {
                    warn(`warn_choose_all`); return false;
                }
            } else if (round === 3) {
                const ac = document.getElementById(`actionInput`);
                const au = document.getElementById(`authorityInput`);
                const vi = document.getElementById(`visibilityInput`);
                const sp = document.getElementById(`spendInput`);
                if (ac) decisions.action = ac.value;
                if (au) decisions.authority = au.value;
                if (vi) decisions.visibility = vi.value;
                if (sp) decisions.spend = parseFloat(sp.value);
                if (!Number.isFinite(decisions.spend) || decisions.spend < 0) {
                    warn(`warn_spend_value`); return false;
                }
            } else if (round === 4) {
                const fo = document.getElementById(`followInput`);
                const cr = document.getElementById(`credRebuildInput`);
                const pi = document.getElementById(`pipelineInput`);
                const cv = document.getElementById(`convictionInput`);
                if (fo) decisions.follow = fo.value;
                if (cr) decisions.credRebuild = cr.value;
                if (pi) decisions.pipeline = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let regretDelta = 0, credDelta = 0, spendDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the signal (Common Error 1: acting before diagnosing).
                switch (d.diagnosis) {
                    case `regret`:
                        ds.diagnosedRegret = true;
                        regretDelta += 14; credDelta += 0.4; coachKey = `coach_r1_regret`; break;
                    case `relationship`:
                        regretDelta += 3; coachKey = `coach_r1_relationship`; break;
                    case `pay`:
                        regretDelta -= 4; coachKey = `coach_r1_pay`; break;
                    case `mood`:
                        regretDelta -= 6; credDelta -= 0.3; coachKey = `coach_r1_mood`; break;
                }

                switch (d.test) {
                    case `meaning`: regretDelta += 7; if (d.diagnosis === `regret`) coachKey = `coach_r1_sharp`; break;
                    case `recruiter`: regretDelta += 2; break;
                    case `none`: regretDelta -= 5; coachKey = `coach_r1_notest`; break;
                }

                switch (d.credSelf) {
                    case `forming`: credDelta += 0.6; break;
                    case `proven`: credDelta -= 0.4; coachKey = (coachKey === `coach_default`) ? `coach_r1_proven` : coachKey; break;
                    case `irrelevant`: credDelta -= 0.6; coachKey = (coachKey === `coach_default`) ? `coach_r1_irrelevant` : coachKey; break;
                }

                // Diagnostic confidence must be EARNED — high confidence on a wrong
                // or untested read is overconfidence, not insight.
                const wellGrounded = (d.diagnosis === `regret` && d.test === `meaning`);
                if (d.confidence >= 70 && !wellGrounded) {
                    regretDelta -= 4; coachKey = `coach_r1_overconfident`;
                } else if (d.confidence >= 60 && wellGrounded) {
                    regretDelta += 4; credDelta += 0.3;
                } else if (d.confidence <= 20) {
                    regretDelta -= 1;
                }

                summaryKey = (d.diagnosis === `regret` && d.test === `meaning`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Presence & the conversation (Common Errors 3 & 4).
                // Timing first — parking it behind the deadline closes the window (HARD).
                switch (d.timing) {
                    case `thisweek`:
                        regretDelta += 6; credDelta += 0.4; break;
                    case `afterdeadline`:
                        ds.parkedIt = true; ds.windowOpen = false;
                        regretDelta -= 14; credDelta -= 1.0; coachKey = `coach_r2_parked`; break;
                    case `vague`:
                        ds.parkedIt = true; ds.windowOpen = false;
                        regretDelta -= 10; credDelta -= 0.8; coachKey = `coach_r2_vague`; break;
                }

                // Modality — presence as a finite, signalling resource.
                switch (d.modality) {
                    case `inperson`:
                        regretDelta += 9; credDelta += 0.6; if (coachKey === `coach_default`) coachKey = `coach_r2_inperson`; break;
                    case `quickcall`:
                        regretDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r2_quickcall` : coachKey; break;
                    case `text`:
                        regretDelta -= 8; credDelta -= 0.4; coachKey = (coachKey === `coach_default`) ? `coach_r2_text` : coachKey; break;
                }

                // Default-virtual avoidance: a thin channel AND a non-stay design = the trap.
                if ((d.modality === `quickcall` || d.modality === `text`) && d.design !== `stay`) {
                    ds.defaultVirtual = true;
                }

                // Design of the conversation.
                switch (d.design) {
                    case `stay`:
                        regretDelta += 10; credDelta += 0.5; if (coachKey === `coach_default`) coachKey = `coach_r2_stay`; break;
                    case `retain`:
                        regretDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r2_retain` : coachKey; break;
                    case `interrogate`:
                        regretDelta -= 4; credDelta -= 0.3; coachKey = (coachKey === `coach_default`) ? `coach_r2_interrogate` : coachKey; break;
                }

                // What the wider team sees (team-level signalling).
                switch (d.team) {
                    case `signal`: credDelta += 0.9; regretDelta += 2; break;
                    case `allin`: credDelta -= 0.5; coachKey = (coachKey === `coach_default`) ? `coach_r2_allin` : coachKey; break;
                    case `hidden`: credDelta -= 0.2; break;
                }

                summaryKey = (d.modality === `inperson` && d.timing === `thisweek` && d.design === `stay`) ? `sum_r2_good` :
                             (ds.parkedIt ? `sum_r2_parked` :
                             (ds.defaultVirtual ? `sum_r2_virtual` : `sum_r2_weak`));
            } else if (round === 3) {
                // Choose the development action (Common Errors 2 & 5).
                // Acting blind: committing an action with no regret diagnosis.
                if (!ds.diagnosedRegret) {
                    ds.actedBlind = true;
                }

                switch (d.action) {
                    case `recraft`:
                        regretDelta += 14; credDelta += 0.5; coachKey = `coach_r3_recraft`; break;
                    case `coaching`:
                        regretDelta += 6; spendDelta += 8; break;
                    case `vague`:
                        regretDelta -= 8; credDelta -= 0.5; coachKey = `coach_r3_vague`; break;
                    case `comp`:
                        // Transactional fix — if the problem is meaning, this makes it worse.
                        regretDelta -= 6; spendDelta += 35;
                        if (ds.diagnosedRegret) { ds.boughtMeaning = true; regretDelta -= 6; coachKey = `coach_r3_comp_regret`; }
                        else { coachKey = `coach_r3_comp`; }
                        break;
                }

                // Authority split (Common Error 5: over-promising).
                switch (d.authority) {
                    case `splitclean`:
                        credDelta += 1.2; regretDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r3_split`; break;
                    case `promiseall`:
                        ds.overPromised = true; credDelta -= 1.6; regretDelta += 2; coachKey = `coach_r3_promiseall`; break;
                    case `commitnothing`:
                        credDelta -= 0.6; regretDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_commitnothing` : coachKey; break;
                }

                // Sponsorship / visibility element.
                switch (d.visibility) {
                    case `escalated`: regretDelta += 5; credDelta += 0.5; break;
                    case `overpromise`: ds.overPromised = true; credDelta -= 1.0; coachKey = (coachKey === `coach_default`) ? `coach_r3_visover` : coachKey; break;
                    case `none`: regretDelta -= 1; break;
                }

                // Spend against the ~£95k cost of losing her.
                spendDelta += d.spend;
                if (d.spend >= 40) {
                    // A large package on a meaning problem signals pay-buys-loyalty.
                    if (ds.diagnosedRegret) { ds.boughtMeaning = true; regretDelta -= 5; }
                    credDelta -= 0.4;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_heavyspend`;
                } else if (d.spend <= 0 && d.action === `comp`) {
                    // Chose a comp action but funded nothing — incoherent.
                    regretDelta -= 2;
                }

                summaryKey = (d.action === `recraft` && d.authority === `splitclean` && !ds.boughtMeaning) ? `sum_r3_good` :
                             (ds.boughtMeaning ? `sum_r3_bought` :
                             (ds.overPromised ? `sum_r3_overpromised` :
                             (ds.actedBlind ? `sum_r3_blind` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Build the adjustment & recover credibility (Recover).
                switch (d.follow) {
                    case `plan90`:
                        regretDelta += 10; credDelta += 0.8; coachKey = `coach_r4_plan90`; break;
                    case `monitor`:
                        regretDelta += 1; coachKey = `coach_r4_monitor`; break;
                    case `oneoff`:
                        regretDelta -= 7; credDelta -= 0.5; coachKey = `coach_r4_oneoff`; break;
                }

                switch (d.credRebuild) {
                    case `model`:
                        credDelta += 1.0; regretDelta += 3; if (coachKey === `coach_default`) coachKey = `coach_r4_model`; break;
                    case `silent`:
                        credDelta -= 0.2; break;
                    case `broadcast`:
                        credDelta -= 0.7; coachKey = (coachKey === `coach_default`) ? `coach_r4_broadcast` : coachKey; break;
                }

                switch (d.pipeline) {
                    case `connect`:
                        credDelta += 0.6; regretDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r4_connect`; break;
                    case `tokenise`:
                        credDelta -= 0.6; regretDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_tokenise` : coachKey; break;
                    case `ignore`:
                        credDelta -= 0.3; break;
                }

                if (d.conviction >= 60) { credDelta += 0.3; regretDelta += 2; }
                else if (d.conviction <= 25) { credDelta -= 0.3; regretDelta -= 2; }

                summaryKey = (d.follow === `plan90` && d.credRebuild === `model` && d.pipeline === `connect`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.regret = Math.max(0, Math.min(100, Math.round((ds.regret + regretDelta) * 10) / 10));
            ds.credibility = Math.max(0, Math.min(10, Math.round((ds.credibility + credDelta) * 10) / 10));
            ds.budget = Math.min(this.SPEND_CAP, Math.round((ds.budget + spendDelta) * 10) / 10);

            // ---- STICKY CAPS — the headline anti-patterns cannot reach the top.
            // Parking it shuts the window: regret resolution is hard-capped because the
            // decision was effectively made by her recruiter, not by you.
            if (ds.parkedIt) ds.regret = Math.min(ds.regret, 45);
            // Acting before diagnosing caps regret — you fixed a symptom, not the cause.
            if (ds.actedBlind) ds.regret = Math.min(ds.regret, 55);
            // Buying a meaning problem accelerates the exit: regret stays capped low.
            if (ds.boughtMeaning) ds.regret = Math.min(ds.regret, 50);
            // Over-promising beyond authority caps credibility regardless of later rounds.
            if (ds.overPromised) ds.credibility = Math.min(ds.credibility, 5.5);

            // ---- Stay probability is DERIVED: she stays when the regret signal is being
            // resolved, the leader is credible, and the window is still open. ----
            const regretFactor = ds.regret / 100;                       // 0..1
            const credFactor = ds.credibility / 10;                     // 0..1
            const windowFactor = ds.windowOpen ? 1 : 0.55;              // closed window slashes the odds
            let stay = (0.62 * regretFactor + 0.38 * credFactor) * windowFactor * 100;
            // Transactional fixes for a meaning problem do not actually keep her.
            if (ds.boughtMeaning) stay = Math.min(stay, 48);
            ds.stayProb = Math.max(0, Math.min(100, Math.round(stay)));

            ds.regretHistory.push(ds.regret);
            ds.stayHistory.push(ds.stayProb);
            ds.credHistory.push(ds.credibility);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                regret: ds.regret,
                regretDelta: Math.round(regretDelta * 10) / 10,
                stayProb: ds.stayProb,
                credibility: ds.credibility,
                credDelta: Math.round(credDelta * 10) / 10,
                budget: ds.budget,
                windowOpen: ds.windowOpen,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _credLabel(v) {
            return this._fmtOneDecimal(v);
