        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`regretDisplay`, `domainState.regret`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`stayDisplay`, `domainState.stayProb`, (v) => {
                const s = Math.round(Number(v));
                const card = document.querySelector(`.crossroads-card-stay`);
                if (card) {
                    card.classList.toggle(`crossroads-stay-danger`, s < 50);
                    card.classList.toggle(`crossroads-stay-good`, s >= 70);
                }
                return `${s}%`;
            });

            uiManager.bind(`credDisplay`, `domainState.credibility`, (v) => self._fmtOneDecimal(Number(v)));

            uiManager.bind(`budgetDisplay`, `domainState.budget`, (v) => {
                const n = Number(v);
                return n >= 1 ? `£${Math.round(n)}k` : `£0`;
            });

            uiManager.bind(`windowDisplay`, `domainState.windowOpen`, (v) => {
                const open = (v === true || v === `true`);
                const bar = document.querySelector(`.crossroads-window-bar`);
                const period = window.mySimulation && window.mySimulation.state ? (window.mySimulation.state.currentPeriod || 1) : 1;
                if (bar) {
                    bar.classList.toggle(`crossroads-window-closed`, !open);
                    bar.classList.toggle(`crossroads-window-tight`, open && period >= 2);
                }
                if (!open) return window.mySimulation.t(`window_closed`);
                const daysLeft = Math.max(0, self.WINDOW_DAYS - (period - 1));
                return `${window.mySimulation.t(`window_open`)} · ${daysLeft} ${window.mySimulation.t(`window_days`)}`;
            });

            // Confidence slider readout.
            const cf = document.getElementById(`confidenceInput`);
            const cfReadout = document.getElementById(`confidenceReadout`);
            if (cf && cfReadout) {
                cfReadout.textContent = cf.value;
                cf.addEventListener(`input`, function() { cfReadout.textContent = cf.value; });
            }
        }

        _fmtOneDecimal(v) {
            // Locale-aware one-decimal score: en "5.0", es "5,0".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

