        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.regretHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Credibility is /10 — scale ×10 to share the 0–100 axis.
            const credScaled = ds.credHistory.map((v) => Math.round(v * 10));
            return {
                crossroadsChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.regretHistory.map((v) => Math.round(v)) },
                        { data: ds.stayHistory.map((v) => Math.round(v)) },
                        { data: credScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, single source of truth, persisted every period so the
            // grading/analytics/LTI layer (domainState.performance.overallScore then top-level
            // score) receives a number instead of null -> 0.0.
            const regret = Math.round(ds.regret);
            const stayProb = Math.round(ds.stayProb);
            const credibility = Math.round(ds.credibility * 10) / 10;
            const credScore = credibility * 10;
            return Math.round(regret * 0.42 + stayProb * 0.33 + credScore * 0.25);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const regret = Math.round(ds.regret);
            const stayProb = Math.round(ds.stayProb);
            const credibility = Math.round(ds.credibility * 10) / 10;
            const budget = Math.round(ds.budget);

            // Composite: regret resolution, stay probability, credibility — balanced.
            const composite = this._composite(ds);

            const signalRead = ds.diagnosedRegret && regret >= 70;
            const stayed = stayProb >= 70;
            const credible = credibility >= 7;
            const anyFlag = ds.actedBlind || ds.boughtMeaning || ds.defaultVirtual || ds.parkedIt || ds.overPromised;

            let pattern = `mixed`;
            if (ds.parkedIt) pattern = `parked`;
            else if (ds.boughtMeaning) pattern = `transactional`;
            else if (ds.actedBlind) pattern = `blind`;
            else if (ds.overPromised) pattern = `overpromised`;
            else if (ds.defaultVirtual) pattern = `virtual`;
            else if (signalRead && stayed && credible) pattern = `navigated`;

            let performance = `Talent Lost`, performanceKey = `grade_lost`;
            if (signalRead && stayed && credible && !anyFlag && composite >= 75) { performance = `Crossroads Navigated`; performanceKey = `grade_navigated`; }
            else if (stayed && credible && !ds.parkedIt && !ds.boughtMeaning) { performance = `Talent Held`; performanceKey = `grade_held`; }
            else if (ds.parkedIt) { performance = `Window Closed`; performanceKey = `grade_parked`; }
            else if (ds.boughtMeaning) { performance = `Bought the Wrong Problem`; performanceKey = `grade_bought`; }
            else if (ds.overPromised && !credible) { performance = `Credibility Damaged`; performanceKey = `grade_creddamaged`; }
            else if (composite >= 55) { performance = `Mixed Outcome`; performanceKey = `grade_mixed`; }

            const insights = [];
            if (performance === `Crossroads Navigated`) insights.push(window.mySimulation.t(`insight_navigated`));
            else if (pattern === `parked`) insights.push(window.mySimulation.t(`insight_parked`));
            else if (pattern === `transactional`) insights.push(window.mySimulation.t(`insight_transactional`));
            else if (pattern === `blind`) insights.push(window.mySimulation.t(`insight_blind`));
            else if (pattern === `overpromised`) insights.push(window.mySimulation.t(`insight_overpromised`));
            else if (pattern === `virtual`) insights.push(window.mySimulation.t(`insight_virtual`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!ds.diagnosedRegret) insights.push(window.mySimulation.t(`insight_nodiagnosis`));
            if (credibility < 6) insights.push(window.mySimulation.t(`insight_cred_low`));
            if (stayProb < 50) insights.push(window.mySimulation.t(`insight_stay_low`));
            if (signalRead && stayed && credible && budget <= 12) insights.push(window.mySimulation.t(`insight_lowcost`));

            return {
                regret: regret,
                stayProb: stayProb,
                credibility: credibility,
                budget: budget,
                signalRead: signalRead,
                stayed: stayed,
                credible: credible,
                parkedIt: ds.parkedIt,
                boughtMeaning: ds.boughtMeaning,
                actedBlind: ds.actedBlind,
                overPromised: ds.overPromised,
                pattern: pattern,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="crossroads-cm"><p class="crossroads-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="crossroads-cm-kpi"><span class="crossroads-cm-kpi-val">${valStr}</span>`
                + `<span class="crossroads-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="crossroads-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="crossroads-cm">`
                +   `<div class="crossroads-cm-scoreband">`
                +     `<div class="crossroads-cm-score">${summary.composite}<span class="crossroads-cm-score-max">/100</span></div>`
                +     `<div class="crossroads-cm-tier">${tier}</div>`
                +     `<div class="crossroads-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="crossroads-cm-kpis">`
                +     kpi(`cm_kpi_regret`, String(Math.round(summary.regret)))
                +     kpi(`cm_kpi_stay`, String(Math.round(summary.stayProb)) + `%`)
                +     kpi(`cm_kpi_cred`, self._fmtOneDecimal(summary.credibility))
                +     kpi(`cm_kpi_budget`, String(Math.round(summary.budget)))
                +   `</div>`
                +   `<div class="crossroads-cm-chips">`
                +     chip(summary.signalRead, `cm_chip_signal`)
                +     chip(summary.stayed, `cm_chip_stay`)
                +     chip(summary.credible, `cm_chip_cred`)
                +   `</div>`
                +   (insights ? `<ul class="crossroads-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.parkedIt) return window.mySimulation.t(`hint_parked`);
            if (ds.boughtMeaning) return window.mySimulation.t(`hint_transactional`);
            if (ds.overPromised && ds.credibility < 6) return window.mySimulation.t(`hint_overpromised`);
            if (state.currentPeriod >= 2 && !ds.diagnosedRegret) return window.mySimulation.t(`hint_diagnose`);
            if (ds.defaultVirtual) return window.mySimulation.t(`hint_virtual`);
            if (ds.regret >= 70 && ds.stayProb >= 70 && ds.credibility >= 7) return window.mySimulation.t(`hint_strong`);
            return null;
        }

